{
  "packet_id": "H6-T04-1",
  "claim_id": "C043",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C043.component",
    "value": "Roster timing can shift apparent retention.",
    "scope": "A possible influence on observed retention; its magnitude and direction are unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P026",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P026 explicitly identifies roster timing as a condition that can shift apparent retention."
    }
  },
  "signal_basis": {
    "component_id": "C043.signal_basis",
    "value": "Record intended roster dates and follow accounts through their next roster opportunity, observing waiting durations and publication timing. Publication near a previously stated roster date is a candidate timing signal.",
    "scope": "Prospective cohort observations with declared follow-up limits and censoring; the candidate signal is assumed observed for this assessment.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply roster-date collection, follow-up and censoring rules, retention measurements, and the candidate temporal alignment."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C043.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The bounded possibility claim is supported without an additional unresolved empirical relation."
    }
  },
  "rationale": "Waiting duration and publication timing depend on when accounts resume progress. Their observed alignment with previously stated roster opportunities licenses treating roster timing as a possible influence on apparent retention. The claim does not identify a unique cause or assert a measured causal effect.",
  "uncertainty": "The influence's magnitude, direction, prevalence and causal contribution remain unspecified; other causes may produce similar timing.",
  "anomalies": []
}
